Thread t = new Thread(() -> System.out.println("A"));
t.start();   // pede à JVM uma NOVA thread, que executa a tarefa
// t.run();  // só uma chamada de método comum: continua UMA thread!
t.join();    // espera aqui até t terminar
System.out.println("B");   // sempre depois de A

synchronized String take() throws InterruptedException {
    while (items.isEmpty()) {   // WHILE, nunca IF
        wait();
    }
    return items.removeFirst();
}

int old, next;
do {
    old = value.get();          // lê
    next = old + 1;             // calcula
} while (!value.compareAndSet(old, next)); // repete se mudou

async function sequential() {
	await sleep(300);
	await sleep(200);
	await sleep(100);          // total cerca de 600 ms
}
async function together() {
	await Promise.all([sleep(300), sleep(200), sleep(100)]); // cerca de 300 ms
}

